-- 20261126140000_service_category_icons.sql
-- REPO: kisanshaktiai/kisanshakti-ai-v1  (farmer app)
--
-- Service catalogue: one picture for every family and every service, so a
-- farmer or provider who reads little can pick the work by its picture.
--
-- Adds service_categories.icon_path and fills it for the 16 families and 154
-- services. Run AFTER 20261126130000_service_catalogue_india_additions.sql:
-- that file adds 35 of the services pictured here.
--
-- What icon_path holds: the "d" of ONE svg path on a 24 x 24 grid. The app
-- draws it as an outline (no fill, round caps and joins, stroke 1.75 to 2) in
-- the current theme colour, so a white-label tenant's colours apply without
-- any change here. Only path-data characters are accepted (a CHECK below), so
-- the column cannot carry markup or script.
--
-- Where the 170 drawings come from:
--    64 unchanged from Lucide            https://lucide.dev   (ISC licence)
--    18 unchanged from Tabler Icons      https://tabler.io/icons   (MIT licence)
--    88 drawn for this catalogue, some built from Lucide parts
-- The notices those two licences ask to be kept are in
-- docs/licenses/SERVICE_ICONS_NOTICE.md.
--
-- ▶ FLAGGED FOR THE PRODUCT OWNER'S EDIT: a picture can be replaced at any
--   time by updating icon_path; a NULL shows the family's picture instead.
--
-- No table, policy or grant is added: the column is read through the existing
-- read-active policy and table-level SELECT grant. No row is removed.
-- Safe to run twice: a picture is written only where none is set.
-- ═══════════════════════════════════════════════════════════════════════════

-- ── 1. the column ───────────────────────────────────────────────────────────
ALTER TABLE public.service_categories ADD COLUMN IF NOT EXISTS icon_path text;
ALTER TABLE public.service_categories DROP CONSTRAINT IF EXISTS service_categories_icon_path_chk;
ALTER TABLE public.service_categories ADD CONSTRAINT service_categories_icon_path_chk
  CHECK (icon_path IS NULL OR (length(icon_path) BETWEEN 1 AND 4000 AND icon_path ~ '^[MmLlHhVvCcSsQqTtAaZz0-9 ,.-]+$'));
COMMENT ON COLUMN public.service_categories.icon_path IS
  'Picture for this family or service: the d of one SVG path on a 24 x 24 grid, drawn by the app as an outline in the theme colour. NULL shows the family picture.';

-- ── 2. the pictures ─────────────────────────────────────────────────────────
