-- Verification (read-only) ────────────────────────────────────────────────────
SELECT 'families and services that have a picture' AS check_name, count(*)::text AS actual, '170' AS expected
  FROM public.service_categories WHERE icon_path IS NOT NULL;
SELECT 'active families or services without a picture' AS check_name, count(*)::text AS actual, '0' AS expected
  FROM public.service_categories WHERE is_active AND icon_path IS NULL;
SELECT 'services of one family that share the same picture' AS check_name, count(*)::text AS actual, '0' AS expected
  FROM (SELECT parent_code, icon_path FROM public.service_categories
         WHERE parent_code IS NOT NULL AND icon_path IS NOT NULL
         GROUP BY parent_code, icon_path HAVING count(*) > 1) d;
SELECT 'the app can read the picture column' AS check_name,
       has_column_privilege('anon', 'public.service_categories', 'icon_path', 'SELECT')::text AS actual, 'true' AS expected;
